#ifndef TEST_SUPPORT_H
#define TEST_SUPPORT_H

#include <stdbool.h>
#include <stdint.h>

#include "fake_flash.h"
#include "sota/boot.h"
#include "sota/bootstate.h"
#include "sota/image.h"

typedef struct {
    uint8_t *data;
    uint32_t len;
} vector_t;

/* Load test/vectors/<name>.bin (generated by tools/gen_test_vectors.py). */
vector_t vector_load(const char *name);
void vector_free(vector_t *v);

/* Keyring holding the development public key. */
const sota_keyring_t *test_keyring(void);

/* Program an image straight into its slot, like a factory programmer would. */
void install_image(fake_flash_t *f, unsigned slot, const vector_t *image);

/* One bootloader run: open the journal, decide, persist. Returns the slot to
 * boot or SOTA_RECOVERY, or -2 if the flash failed. */
int run_bootloader(fake_flash_t *f, sota_bootstate_t *state_out);

/* sota_probe_fn backed by sota_image_verify on the fake flash. */
void probe_with_verify(void *ctx, unsigned slot, sota_slot_info_t *info);

#endif /* TEST_SUPPORT_H */
